WITH flattened AS (SELECT id, service, log_ts, level, latency_ms, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS k, v), unpacked AS (SELECT id, k, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS has_fault FROM flattened WHERE k <> 'trace'), scored AS (SELECT *, SUM(status_code_high) OVER (PARTITION BY k ORDER BY has_fault, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_status_code_high, RANK() OVER w_recent AS has_fault_rank, RANK() OVER (PARTITION BY k ORDER BY has_fault NULLS LAST) AS has_fault_rank_2 FROM unpacked WINDOW w_recent AS (PARTITION BY k ORDER BY has_fault DESC NULLS FIRST)), base AS (SELECT id, k, status_code_high, has_fault, cumulative_status_code_high, has_fault_rank, has_fault_rank_2, ROUND(has_fault_rank_2 * 1.07, 2) AS has_fault_rank_2_scaled FROM scored WHERE k IS NOT NULL) SELECT CASE WHEN has_fault_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END AS has_fault_rank_tier, CASE WHEN cumulative_status_code_high >= 10 THEN 'PREMIUM' ELSE 'STANDARD' END AS cumulative_status_code_high_tier, k, COUNT(*) FILTER (WHERE k = 'trace') AS trace_rows, COUNT(DISTINCT id) AS distinct_ids, SUM(CASE WHEN k = 'version' THEN status_code_high ELSE 0 END) AS version_status_code_high FROM base GROUP BY CASE WHEN has_fault_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN cumulative_status_code_high >= 10 THEN 'PREMIUM' ELSE 'STANDARD' END, k ORDER BY has_fault_rank_tier DESC
